/* SDF primitives */
// Sphere - not used
float SDFSphere(vec3 position, float radius) {
    return length(position)-radius;
}
// Box - not used
float SDFBox(vec3 position, vec3 size) {
    vec3 q = abs(position) - 0.5 * size;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}
// Torus
float SDFTorus(vec3 position, float R, float r) {
  vec2 q = vec2(length(position.xz)-R,position.y);
  return length(q)-r;
}
// Cylinder - not used
float SDFCylinder(vec3 position, float height, float radius) {
  vec2 radialDistance = abs(vec2(length(position.xz),position.y)) - vec2(radius,height);
  return min(max(radialDistance.x,radialDistance.y),0.0) + length(max(radialDistance,0.0));
}


/* SDF transformations */
// 3D rotations
// Rotate point around arbitrary axis
// https://suricrasia.online/blog/shader-functions/
vec3 erot(vec3 point, vec3 axis, float theta) {
    return mix(dot(axis, point)*axis, point, cos(theta)) + sin(theta)*cross(axis,point);
}

// Rotate point around main axis
vec3 rotateX(vec3 point, float theta) {return erot(point, vec3(1,0,0), theta);}
vec3 rotateY(vec3 point, float theta) {return erot(point, vec3(0,1,0), theta);}
vec3 rotateZ(vec3 point, float theta) {return erot(point, vec3(0,0,1), theta);}

// Twist point around main axis
vec3 twistX(vec3 point, float twist) {return erot(point, vec3(1,0,0), -point.x * twist);}
vec3 twistY(vec3 point, float twist) {return erot(point, vec3(0,1,0), point.y * twist);}
vec3 twistZ(vec3 point, float twist) {return erot(point, vec3(0,0,1), -point.z * twist);}


/* SDF operators */
float opSmoothUnion(float d1, float d2, float k) {
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float opSmoothSubtraction(float d1, float d2, float k) {
    float h = clamp( 0.5 - 0.5*(d2+d1)/k, 0.0, 1.0 );
    return mix( d2, -d1, h ) + k*h*(1.0-h);
}

float opSmoothIntersection(float d1, float d2, float k) {
    float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) + k*h*(1.0-h);
}

/* Scene */
// This function defines the scene by returning the distance of the nearest point from given
// position. Also sets the material ID for that point, via the "out" argument.
float map(in vec3 position, out int materialID)
{
    // Torus SDF wasn't orientated how I liked, so instead
    // of fixing that, I just rotated "world coordinates"
    position = position.xzy;

    // Set material ID, based on position
    materialID = 0; // Body
    if (position.z < 0.005)
        materialID = 1; // Floor

    // Sculpture is made up from 2 distorted tori, combined smoothly
    return min(
        opSmoothUnion(
            SDFTorus(twistX(twistZ(position, 1.5), 0.4), 3.0, 0.2+0.1*sin(2.0*position.y)+0.1*cos(3.0*position.z)),
            SDFTorus(twistZ(position, 0.3), 3.0, 0.7*cos(0.6*position.z)),
            2.0),
        // Ground plane at 0 height
        position.z)
        // Divider is needed due to space transformations (distance estimator overshoots)
        // Exact value is based on trial and error.
        / 5.0;
}

// Ray marching: Follow a ray of light from camera origin until collision to find distance
// and material. Material ID is passed along using the "out" argument.
float castRay(in vec3 rayOrigin, vec3 rayDirection, out int materialID) {
    // Start from origin
    float distance = 0.0;
    for(int i=0; i<1024; i++) {
        // Find stepsize for marching (distance of closest point from current position)
        float step = map(rayOrigin + distance * rayDirection, materialID);

        // An object is hit
        if(step < 0.001)
            return distance;

        // March!
        distance += step;

        // If ray doesn't hit any objects and maximum render distance is reached,
        // draw the background
        if(length(rayOrigin + distance * rayDirection) > 8.0) {
            // Return a negative distance, so background is not affected by lighting.
            return -1.0;
        }
    } 
}

// Calculate surface normal
// https://iquilezles.org/articles/normalsSDF/
vec3 calculateNormal(vec3 p) {
    const float EPS = 0.001;
    int dummy;
    vec3 v1 = vec3(
        map(p + vec3(EPS,  0 ,  0 ), dummy),
        map(p + vec3( 0 , EPS,  0 ), dummy),
        map(p + vec3( 0 ,  0 , EPS), dummy));
    vec3 v2 = vec3(
        map(p - vec3(EPS,  0 ,  0 ), dummy),
        map(p - vec3( 0 , EPS,  0 ), dummy),
        map(p - vec3( 0 ,  0 , EPS), dummy));

    return normalize(v1 - v2);
}

// Calculate soft shadows
// Thanks iq!
// https://iquilezles.org/articles/rmshadows/
float softShadow(in vec3 rayOrigin, vec3 rayDirection)
{
    float res = 1.0;
    float distance = 0.0;   // Min distance
    int dummy;
    while (distance < 16.0) // Max distance
    {
        float step = map(rayOrigin + distance * rayDirection, dummy);
        if(step < 0.001)
            return 0.0;
        res = min(res, 8.0 * step/distance ); // hardness = 8
        distance += step;
    }
    return res;
}

// Calculate ambient occlusions
// Stole it from here:
// https://www.shadertoy.com/view/3lsSzf
float calcOcclusion(vec3 pos, in vec3 nor)
{
	float occ = 0.0;
    float sca = 1.0;
    int dummy;
    for(int i=0; i<5; i++)
    {
        float h = 0.01 + 0.11*float(i)/4.0;
        vec3 opos = pos + h*nor;
        occ += (h-map(opos, dummy))*sca;
        sca *= 0.95;
    }
    return clamp(1.0 - 2.0*occ, 0.0, 1.0);
}

// Calculates the color of a point by shooting a ray from the origin in the
// specified direction and calculating every texture and lighting effect for
// the surface that is hit.
// Ray origin and direction parameters are altered if a reflective surface is hit.
// Also sets the reflectivity for the surface hit, via the "out" argument.
vec3 render(inout vec3 rayOrigin, inout vec3 rayDirection, out vec3 reflectivity)
{
    // Perform ray marhcing:
    // This finds the material and distance for the current pixel.
    int materialID;
    float distance = castRay(rayOrigin, rayDirection, materialID);

    if(distance > 0.0) {
        // Ray hit
        vec3 position = rayOrigin + distance * rayDirection;
        vec3 normal = calculateNormal(position);

        // Light Source
        vec3 light1Color = vec3(1);
        vec3 light1Direction = vec3(0,1,0);

        // Diffused light
        float diffusedLight1 = dot(normal, light1Direction) * 0.5 + 0.5;

        // Soft shadows
        float shadow1 = clamp(softShadow(position + 0.001 * normal, light1Direction), 0.1, 1.0);

        // Ambient occlusion
        float occlusion = calcOcclusion(position, normal);

        // Object color
        vec3 objectColor;
        // Body - Solid Orange
        objectColor = vec3(1.0, 0.3, 0.0);
        // Floor - Checkerboard pattern
        if (materialID == 1) {
            vec2 s = sign(fract(position.xz * 0.5)-0.5);
            objectColor = vec3(0.2 - 0.1*s.x*s.y);
        }

        //Mixing lights and shadows
        vec3 diffused = objectColor * light1Color * diffusedLight1;
        diffused *= shadow1;
        diffused *= occlusion;

        // Reflection
        // Body - Red tinted reflection regardless of surface orientation - "metallic shine"
        reflectivity = vec3(0.5, 0.1, 0.1);
        // Floor - Clear reflection, but reflectivity is varied based on surface orientation - "glassy shine"
        if (materialID == 1)
            reflectivity = vec3(clamp(pow(1.0 - clamp(dot(normal, -rayDirection), 0.0, 1.0), 5.0), 0.0, 0.1));

        // Set up new ray origin and direction for rendering reflections
        rayOrigin = position+normal*0.001; // Move slightly to make sure we're not in a surface
        rayDirection = reflect(rayDirection, normal); // Reflect on surface


        return diffused;
    }

    // If nothing was hit - background
    reflectivity = vec3(0); // Background shouldn't reflect
    return texture(iChannel0, rayDirection).rgb; // Draw background cubemap
}

// Main rendering function - first entry point
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Pixel coordinates (from -1 to 1)
    vec2 uv = (2.0*floor(fragCoord)-iResolution.xy)/iResolution.y;

    // Camera position and target point
    // Camera is moved around a circle pointing to the center
    float r = 5.0;
    float h = 1.0;
    vec3 rayOrigin = vec3(r*sin(iTime/10.0),h,r*cos(iTime/10.0));
    vec3 cameraPointingAt = vec3(0,1,0);
    float zoom = 2.0;

    // Calculating ray angles
    vec3 ww = normalize(vec3(cameraPointingAt - rayOrigin));
    vec3 uu = normalize(cross(ww, vec3(0,1,0)));
    vec3 vv = normalize(cross(uu, ww));

    vec3 rayDirection = normalize (ww*zoom + uv.x*uu + uv.y*vv);

    // Render Scene

    // Surface reflectivity from different iterations
    vec3 reflectivity;
    // Combined reflectivity that is carried througout the different passes
    vec3 combinedReflectivity = vec3(1);
    // Perform first render pass from camera
    vec3 color = render(rayOrigin, rayDirection, reflectivity);

    // Additional render passes for reflections, and reflections of reflections, etc.
    const int REFLECTIONS = 4;
    for(int i=0; i<REFLECTIONS; i++) {
        // Combined reflectivity that is reduced with every additional reflection
        combinedReflectivity *= reflectivity;
        // Mix in reflection to final color
        color += combinedReflectivity * render(rayOrigin, rayDirection, reflectivity);
    }

    // Gamma correction
    color = pow(color, vec3(0.4545));

    // Output to screen
    fragColor = vec4(color,1.0);
}
